{
  "name": "Nova Dome VR",
  "description": "A high-fidelity immersive planetarium simulator that projects local video files onto a 3D hemisphere, fully VR-compatible for a seated dome experience.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface VideoData {
  url: string;
  name: string;
  type: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

import { GoogleGenAI } from "@google/genai";

export const getGeminiResponse = async (userPrompt: string, currentVideoName: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are 'Nova', a brilliant and friendly Virtual Astronomer. 
    The user is currently inside a simulated 3D Planetarium (a fulldome environment).
    The user is watching a video named: "${currentVideoName}".
    If the user asks about astronomy, space, or planetarium mechanics, answer with passion and scientific accuracy.
    If the user asks about the app, explain that it maps local videos onto a 3D hemisphere to simulate a dome.
    Keep responses concise and atmospheric.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.8,
      },
    });

    return response.text || "I'm gazing at the stars... could you repeat that?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "The cosmos is silent for a moment. Please check your connection.";
  }
};

import React, { useRef, useEffect } from 'react';
import { useThree, useFrame } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, Stars } from '@react-three/drei';
import * as THREE from 'three';

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
}

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null }> = ({ videoElement }) => {
  const meshRef = useRef<THREE.Mesh>(null!);
  const textureRef = useRef<THREE.VideoTexture | null>(null);

  useEffect(() => {
    if (videoElement) {
      const texture = new THREE.VideoTexture(videoElement);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textureRef.current = texture;

      if (meshRef.current) {
        const material = meshRef.current.material as THREE.MeshBasicMaterial;
        material.map = texture;
        material.needsUpdate = true;
      }
    }
  }, [videoElement]);

  return (
    <Sphere 
      ref={meshRef} 
      args={[100, 64, 64, 0, Math.PI * 2, 0, Math.PI / 2]} 
      rotation={[0, Math.PI, 0]}
    >
      <meshBasicMaterial 
        side={THREE.BackSide} 
        color="#ffffff" 
        transparent 
      />
    </Sphere>
  );
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying }) => {
  return (
    <>
      <color attach="background" args={['#000000']} />

      <PerspectiveCamera makeDefault position={[0, 1.6, 0]} />

      <Stars 
        radius={100} 
        depth={50} 
        count={5000} 
        factor={4} 
        saturation={0} 
        fade 
        speed={1} 
      />

      <DomeProjection videoElement={videoElement} />

      <gridHelper args={[20, 20, 0x333333, 0x111111]} position={[0, -0.1, 0]} />

      <ambientLight intensity={0.5} />
      <pointLight position={[10, 10, 10]} />
    </>
  );
};

export default Scene;

import React, { useState, useRef, useEffect } from 'react';
import { getGeminiResponse } from '../services/geminiService';
import { ChatMessage } from '../types';

interface AIAssistantProps {
  currentVideoName: string;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ currentVideoName }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'assistant', content: "Greetings! I am Nova. What celestial wonders are we exploring today?" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsLoading(true);

    const response = await getGeminiResponse(userMsg, currentVideoName);
    setMessages(prev => [...prev, { role: 'assistant', content: response }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-24 right-6 w-80 bg-slate-900/80 backdrop-blur-md border border-slate-700 rounded-xl flex flex-col shadow-2xl overflow-hidden z-50">
      <div className="p-3 border-b border-slate-700 flex items-center gap-2 bg-slate-800/50">
        <div className="w-2 h-2 bg-blue-400 rounded-full animate-pulse"></div>
        <span className="text-sm font-bold tracking-wider uppercase text-blue-200">Nova Astronomer</span>
      </div>

      <div ref={scrollRef} className="h-64 overflow-y-auto p-4 space-y-4">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-lg text-sm ${
              m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-200'
            }`}>
              {m.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-800 p-3 rounded-lg flex gap-1">
              <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
              <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-3 bg-slate-800/30 flex gap-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Ask Nova about the stars..."
          className="flex-1 bg-slate-900 border border-slate-700 rounded-md px-3 py-1.5 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button 
          onClick={handleSend}
          className="bg-blue-600 hover:bg-blue-500 text-white px-3 py-1 rounded text-xs transition-colors"
        >
          Send
        </button>
      </div>
    </div>
  );
};

export default AIAssistant;

import React from 'react';

interface ControlsProps {
  isPlaying: boolean;
  onTogglePlay: () => void;
  onFileSelect: (e: React.ChangeEvent<HTMLInputElement>) => void;
  videoName: string;
  progress: number;
}

const Controls: React.FC<ControlsProps> = ({ isPlaying, onTogglePlay, onFileSelect, videoName, progress }) => {
  return (
    <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[90%] max-w-2xl bg-slate-900/60 backdrop-blur-xl border border-white/10 rounded-2xl p-4 flex flex-col gap-4 shadow-2xl z-50">
      <div className="flex items-center justify-between gap-6">
        <div className="flex items-center gap-4 flex-1">
          <button 
            onClick={onTogglePlay}
            className="w-12 h-12 flex items-center justify-center bg-white text-slate-900 rounded-full hover:bg-blue-100 transition-all active:scale-95 shadow-lg"
          >
            {isPlaying ? (
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
            )}
          </button>

          <div className="flex flex-col flex-1 overflow-hidden">
            <span className="text-xs font-semibold text-slate-400 uppercase tracking-tighter">Now Projecting</span>
            <span className="text-sm font-medium text-white truncate">{videoName || 'No Video Selected'}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <label className="cursor-pointer bg-slate-800 hover:bg-slate-700 text-white px-4 py-2 rounded-lg text-sm font-medium border border-slate-600 transition-colors whitespace-nowrap">
            Select Video
            <input 
              type="file" 
              accept="video/*" 
              onChange={onFileSelect} 
              className="hidden" 
            />
          </label>
        </div>
      </div>

      <div className="relative w-full h-1 bg-slate-700 rounded-full overflow-hidden">
        <div 
          className="absolute top-0 left-0 h-full bg-blue-500 transition-all duration-300" 
          style={{ width: `${progress}%` }}
        />
      </div>
    </div>
  );
