export default Controls;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { XR, VRButton, Controllers, Hands } from '@react-three/xr';
import Scene from './components/Scene';
import Controls from './components/Controls';
import AIAssistant from './components/AIAssistant';
import { VideoData } from './types';

const App: React.FC = () => {
  const [video, setVideo] = useState<VideoData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  // Initialize persistent video element
  useEffect(() => {
    const v = document.createElement('video');
    v.crossOrigin = 'anonymous';
    v.loop = true;
    v.playsInline = true;

    const updateProgress = () => {
      if (v.duration) {
        setProgress((v.currentTime / v.duration) * 100);
      }
    };

    v.addEventListener('timeupdate', updateProgress);
    videoRef.current = v;

    return () => {
      v.pause();
      v.removeEventListener('timeupdate', updateProgress);
      v.src = '';
    };
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      setVideo({
        url,
        name: file.name,
        type: file.type
      });

      videoRef.current.src = url;
      videoRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch(err => console.error("Playback failed:", err));
    }
  };

  const togglePlay = useCallback(() => {
    if (!videoRef.current || !video) return;

    if (isPlaying) {
      videoRef.current.pause();
    } else {
      videoRef.current.play();
    }
    setIsPlaying(!isPlaying);
  }, [isPlaying, video]);

  return (
    <div className="w-full h-screen relative bg-black">
      {/* VR Integration */}
      <VRButton className="!fixed !top-6 !right-6 !z-[100] !bg-blue-600 !px-6 !py-3 !rounded-full !border-none !text-white !font-bold !shadow-xl hover:!bg-blue-500 transition-colors" />

      {/* 3D Viewport */}
      <div className="absolute inset-0 z-0">
        <Canvas>
          <XR>
            <Scene videoElement={videoRef.current} isPlaying={isPlaying} />
            <Controllers />
            <Hands />
          </XR>
        </Canvas>
      </div>

      {/* Overlay UI */}
      {!video && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
          <div className="p-8 bg-slate-900/80 backdrop-blur-md rounded-3xl border border-white/10 text-center max-w-md shadow-2xl pointer-events-auto">
            <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-4 tracking-tighter">
              NOVA DOME
            </h1>
            <p className="text-slate-300 mb-8 text-sm leading-relaxed">
              Experience local media in a simulated fulldome environment. 
              Upload a video to begin your celestial journey. VR ready for Meta Quest and compatible headsets.
            </p>
            <label className="inline-block bg-white text-slate-900 px-8 py-4 rounded-xl font-bold cursor-pointer hover:bg-blue-50 transition-all shadow-lg active:scale-95">
              Launch Video
              <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
            </label>
          </div>
        </div>
      )}

      {video && (
        <>
          <Controls 
            isPlaying={isPlaying} 
            onTogglePlay={togglePlay} 
            onFileSelect={handleFileChange}
            videoName={video.name}
            progress={progress}
          />
          <AIAssistant currentVideoName={video.name} />
        </>
      )}

      <div className="fixed top-6 left-6 pointer-events-none z-50">
        <div className="flex flex-col gap-1">
          <span className="text-xs font-black text-white/40 tracking-[0.2em] uppercase">Planetarium Mode</span>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>
            <span className="text-white text-sm font-medium">Systems Nominal</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

