import React, { useRef, useEffect, useLayoutEffect } from 'react';
import { useThree } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, Stars, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
}

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null }> = ({ videoElement }) => {
  const meshRef = useRef<THREE.Mesh>(null!);
  const textureRef = useRef<THREE.VideoTexture | null>(null);

  // Apply Polar (Fisheye) UV Mapping to the hemisphere geometry
  useLayoutEffect(() => {
    if (meshRef.current) {
      const geometry = meshRef.current.geometry;
      const uvAttribute = geometry.attributes.uv;
      const posAttribute = geometry.attributes.position;

      const vec = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vec.fromBufferAttribute(posAttribute, i);
        vec.normalize(); // Ensure we're working with unit sphere coordinates

        // Spherical coordinates: 
        // y is up (zenith)
        // x, z are horizontal plane

        // Angle from zenith (+Y)
        const theta = Math.acos(vec.y); // 0 at top, PI/2 at horizon

        // Azimuthal angle in X-Z plane
        // We use -vec.x and vec.z to align the "front" of the video with the front of the dome
        const phi = Math.atan2(vec.z, -vec.x);

        // Dome Master projection (Polar mapping)
        // r = distance from center of circular video (0 to 0.5)
        // The full 180-degree dome uses theta from 0 to PI/2.
        // We map theta=PI/2 to r=0.5
        const r = theta / Math.PI; // Radius in texture space (max 0.5 for PI/2 dome)

        // Map to UV space [0, 1] centered at (0.5, 0.5)
        const u = 0.5 + r * Math.cos(phi);
        const v = 0.5 + r * Math.sin(phi);

        uvAttribute.setXY(i, u, v);
      }
      uvAttribute.needsUpdate = true;
    }
  }, []);

  useEffect(() => {
    if (videoElement) {
      const texture = new THREE.VideoTexture(videoElement);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textureRef.current = texture;

      if (meshRef.current) {
        const material = meshRef.current.material as THREE.MeshBasicMaterial;
        material.map = texture;
        material.needsUpdate = true;
      }
    }
  }, [videoElement]);

  return (
    <Sphere 
      ref={meshRef} 
      // args: [radius, widthSegments, heightSegments, phiStart, phiLength, thetaStart, thetaLength]
      // thetaLength = PI/2 creates exactly a hemisphere
      args={[100, 128, 128, 0, Math.PI * 2, 0, Math.PI / 2]} 
      rotation={[0, 0, 0]}
      position={[0, 0, 0]}
    >
      <meshBasicMaterial 
        side={THREE.BackSide} 
        color="#ffffff" 
        transparent 
      />
    </Sphere>
  );
};

