};

const OrientationHandler: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  const { camera } = useThree();
  const rotationRef = useRef(new THREE.Euler(0, 0, 0, 'YXZ'));
  const targetQuaternion = useRef(new THREE.Quaternion());
  const currentQuaternion = useRef(new THREE.Quaternion());

  useEffect(() => {
    if (!enabled) return;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.alpha === null || e.beta === null || e.gamma === null) return;

      // Convert degrees to radians
      const alpha = THREE.MathUtils.degToRad(e.alpha); // Z
      const beta = THREE.MathUtils.degToRad(e.beta);   // X'
      const gamma = THREE.MathUtils.degToRad(e.gamma); // Y''

      const zee = new THREE.Vector3(0, 0, 1);
      const euler = new THREE.Euler();
      const q0 = new THREE.Quaternion();
      const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); // -90 deg fix for landscape/portrait

      // Create quaternion from orientation data
      euler.set(beta, alpha, -gamma, 'YXZ'); 
      targetQuaternion.current.setFromEuler(euler);
      targetQuaternion.current.multiply(q1); // adjust for camera pointing "forward"

      // Additional rotation based on screen orientation might be needed for full robustness,
      // but this basic mapping handles most mobile portrait/landscape look-around cases.
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [enabled]);

  useFrame(() => {
    if (enabled) {
      // Smoothly interpolate to target orientation
      currentQuaternion.current.slerp(targetQuaternion.current, 0.1);
      camera.quaternion.copy(currentQuaternion.current);
    }
  });

  return null;
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying, isMotionEnabled }) => {
