import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { XR, createXRStore } from '@react-three/xr';
import Scene from './components/Scene';
import Controls from './components/Controls';
import AIAssistant from './components/AIAssistant';
import { VideoData } from './types';

const App: React.FC = () => {
  const [video, setVideo] = useState<VideoData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isMotionEnabled, setIsMotionEnabled] = useState(false);
  const [showMotionButton, setShowMotionButton] = useState(false);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  // Check if we are on a mobile device and if we need to show the motion permission button
  useEffect(() => {
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    setShowMotionButton(isMobile);
  }, []);

  const requestMotionPermission = async () => {
    // Standard approach for iOS 13+
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const permissionState = await (DeviceOrientationEvent as any).requestPermission();
        if (permissionState === 'granted') {
          setIsMotionEnabled(true);
        } else {
          alert('Motion permissions are required for the gyroscope to work.');
        }
      } catch (e) {
        console.error('Error requesting motion permission', e);
      }
    } else {
      // Non-iOS or older iOS
      setIsMotionEnabled(!isMotionEnabled);
    }
  };

  // Create the XR store for version 6
  const store = useMemo(() => createXRStore({
    depthSensing: true,
    handTracking: true
  }), []);

  // Initialize persistent video element
  useEffect(() => {
    const v = document.createElement('video');
    v.crossOrigin = 'anonymous';
    v.loop = true;
    v.playsInline = true;

    const updateProgress = () => {
      if (v.duration) {
        setProgress((v.currentTime / v.duration) * 100);
      }
    };

    v.addEventListener('timeupdate', updateProgress);
    videoRef.current = v;

    return () => {
      v.pause();
      v.removeEventListener('timeupdate', updateProgress);
      v.src = '';
    };
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      setVideo({
        url,
        name: file.name,
        type: file.type
      });

      videoRef.current.src = url;
      videoRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch(err => console.error("Playback failed:", err));
    }
  };

  const togglePlay = useCallback(() => {
    if (!videoRef.current || !video) return;

    if (isPlaying) {
      videoRef.current.pause();
    } else {
      videoRef.current.play();
    }
    setIsPlaying(!isPlaying);
  }, [isPlaying, video]);

  return (
    <div className="w-full h-screen relative bg-black">
      {/* Top Right Actions */}
      <div className="fixed top-6 right-6 z-[100] flex flex-col gap-3 items-end">
        {/* VR Toggle */}
        <button 
          onClick={() => store.enterVR()}
          className="bg-blue-600 px-6 py-3 rounded-full text-white font-bold shadow-xl hover:bg-blue-500 transition-colors active:scale-95 flex items-center gap-2"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 10a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-4Z"/><path d="M10 16v-2a2 2 0 0 1 4 0v2"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/></svg>
          Enter VR
        </button>

        {/* Gyro Toggle (Mobile Only) */}
        {showMotionButton && (
          <button 
            onClick={requestMotionPermission}
            className={`px-6 py-3 rounded-full font-bold shadow-xl transition-all active:scale-95 flex items-center gap-2 ${
              isMotionEnabled ? 'bg-green-600 text-white' : 'bg-slate-800 text-slate-300'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 2v4"/><path d="M12 18v4"/><path d="M4.93 4.93l2.83 2.83"/><path d="M16.24 16.24l2.83 2.83"/><path d="M2 12h4"/><path d="M18 12h4"/><path d="M4.93 19.07l2.83-2.83"/><path d="M16.24 7.76l2.83-2.83"/></svg>
            {isMotionEnabled ? 'Gyro Active' : 'Enable Motion'}
          </button>
        )}
      </div>

      {/* 3D Viewport */}
      <div className="absolute inset-0 z-0">
        <Canvas>
          <XR store={store}>
            <Scene 
              videoElement={videoRef.current} 
              isPlaying={isPlaying} 
              isMotionEnabled={isMotionEnabled} 
            />
          </XR>
        </Canvas>
      </div>

      {/* Overlay UI */}
      {!video && (
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
          <div className="p-8 bg-slate-900/80 backdrop-blur-md rounded-3xl border border-white/10 text-center max-w-md shadow-2xl pointer-events-auto">
            <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-4 tracking-tighter">
              NOVA DOME
            </h1>
            <p className="text-slate-300 mb-8 text-sm leading-relaxed">
              Experience local media in a simulated fulldome environment. 
              Upload a video to begin your celestial journey. VR ready for Meta Quest and compatible headsets.
            </p>
            <label className="inline-block bg-white text-slate-900 px-8 py-4 rounded-xl font-bold cursor-pointer hover:bg-blue-50 transition-all shadow-lg active:scale-95">
              Launch Video
              <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
            </label>
          </div>
        </div>
      )}

      {video && (
        <>
          <Controls 
            isPlaying={isPlaying} 
            onTogglePlay={togglePlay} 
            onFileSelect={handleFileChange}
            videoName={video.name}
            progress={progress}
          />
          <AIAssistant currentVideoName={video.name} />
        </>
      )}

      <div className="fixed top-6 left-6 pointer-events-none z-50">
        <div className="flex flex-col gap-1">
          <span className="text-xs font-black text-white/40 tracking-[0.2em] uppercase">Planetarium Mode</span>
          <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full shadow-[0_0_8px_rgba(34,197,94,0.6)] ${isPlaying ? 'bg-green-500' : 'bg-yellow-500'}`}></div>
            <span className="text-white text-sm font-medium">{isPlaying ? 'Systems Nominal' : 'Standby'}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

