import React, { useRef, useEffect, useLayoutEffect, useState } from 'react';
// Import useThree from @react-three/fiber to use it in components inside the Canvas
import { useFrame, useThree } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, Stars, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
  isMotionEnabled: boolean;
}

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null }> = ({ videoElement }) => {
  const meshRef = useRef<THREE.Mesh>(null!);
  const textureRef = useRef<THREE.VideoTexture | null>(null);

  useLayoutEffect(() => {
    if (meshRef.current) {
      const geometry = meshRef.current.geometry;
      const uvAttribute = geometry.attributes.uv;
      const posAttribute = geometry.attributes.position;

      const vec = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vec.fromBufferAttribute(posAttribute, i);
        vec.normalize();

        const theta = Math.acos(vec.y);
        const phi = Math.atan2(vec.z, -vec.x);
        const r = theta / Math.PI; 

        const u = 0.5 + r * Math.cos(phi);
        const v = 0.5 + r * Math.sin(phi);

        uvAttribute.setXY(i, u, v);
      }
      uvAttribute.needsUpdate = true;
    }
  }, []);

  useEffect(() => {
    if (videoElement) {
      const texture = new THREE.VideoTexture(videoElement);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textureRef.current = texture;

      if (meshRef.current) {
        const material = meshRef.current.material as THREE.MeshBasicMaterial;
        material.map = texture;
        material.needsUpdate = true;
      }
    }
  }, [videoElement]);

  return (
    <Sphere 
      ref={meshRef} 
      args={[100, 128, 128, 0, Math.PI * 2, 0, Math.PI / 2]} 
      rotation={[0, 0, 0]}
      position={[0, 0, 0]}
    >
      <meshBasicMaterial 
        side={THREE.BackSide} 
        color="#ffffff" 
        transparent 
      />
    </Sphere>
  );
};

const OrientationHandler: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  // Added useThree hook call and ensured it is imported from @react-three/fiber
  const { camera } = useThree();
  const rotationRef = useRef(new THREE.Euler(0, 0, 0, 'YXZ'));
  const targetQuaternion = useRef(new THREE.Quaternion());
  const currentQuaternion = useRef(new THREE.Quaternion());

  useEffect(() => {
    if (!enabled) return;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.alpha === null || e.beta === null || e.gamma === null) return;

      // Convert degrees to radians
      const alpha = THREE.MathUtils.degToRad(e.alpha); // Z
      const beta = THREE.MathUtils.degToRad(e.beta);   // X'
      const gamma = THREE.MathUtils.degToRad(e.gamma); // Y''

      const zee = new THREE.Vector3(0, 0, 1);
      const euler = new THREE.Euler();
      const q0 = new THREE.Quaternion();
      const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); // -90 deg fix for landscape/portrait

      // Create quaternion from orientation data
      euler.set(beta, alpha, -gamma, 'YXZ'); 
      targetQuaternion.current.setFromEuler(euler);
      targetQuaternion.current.multiply(q1); // adjust for camera pointing "forward"

      // Additional rotation based on screen orientation might be needed for full robustness,
      // but this basic mapping handles most mobile portrait/landscape look-around cases.
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [enabled]);

  useFrame(() => {
    if (enabled) {
      // Smoothly interpolate to target orientation
      currentQuaternion.current.slerp(targetQuaternion.current, 0.1);
      camera.quaternion.copy(currentQuaternion.current);
    }
  });

  return null;
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying, isMotionEnabled }) => {
  return (
    <>
      <color attach="background" args={['#000000']} />

      <PerspectiveCamera makeDefault position={[0, 0, 0.1]} fov={75} />

      {/* Disable OrbitControls if Motion is enabled to prevent fighting */}
      <OrbitControls 
        makeDefault 
        enabled={!isMotionEnabled}
        enablePan={false} 
        minDistance={0.01} 
        maxDistance={80} 
        target={[0, 0, 0]}
        enableDamping={true}
        dampingFactor={0.05}
        rotateSpeed={-0.5} 
      />

      <OrientationHandler enabled={isMotionEnabled} />

      <Stars 
        radius={150} 
        depth={50} 
        count={7000} 
        factor={4} 
        saturation={0} 
        fade 
        speed={1} 
      />

      <DomeProjection videoElement={videoElement} />

      <gridHelper args={[200, 50, 0x333333, 0x111111]} position={[0, -0.1, 0]} />

      <ambientLight intensity={0.5} />
      <pointLight position={[10, 10, 10]} />
    </>
  );
};

export default Scene;

