import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { XR, createXRStore } from '@react-three/xr';
import Scene from './components/Scene';
import Controls from './components/Controls';
import AIAssistant from './components/AIAssistant';
import Settings from './components/Settings';
import { VideoData } from './types';

const App: React.FC = () => {
  const [video, setVideo] = useState<VideoData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isMotionEnabled, setIsMotionEnabled] = useState(false);
  const [showMotionButton, setShowMotionButton] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [domeTilt, setDomeTilt] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const [isUrlModalOpen, setIsUrlModalOpen] = useState(false);
  const [remoteUrl, setRemoteUrl] = useState('');

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const controlsTimerRef = useRef<number | null>(null);

  // Load from URL parameters for embedding support
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const urlParam = params.get('url');
    const tiltParam = params.get('tilt');

    if (urlParam) {
      loadVideoFromUrl(decodeURIComponent(urlParam));
    }
    if (tiltParam) {
      setDomeTilt(parseInt(tiltParam) || 0);
    }
  }, []);

  const loadVideoFromUrl = (url: string) => {
    if (!videoRef.current) return;

    // Simple sanitization for Drive links
    let finalUrl = url;
    if (url.includes('drive.google.com') && url.includes('/file/d/')) {
      const match = url.match(/\/file\/d\/([^\/]+)/);
      if (match && match[1]) {
        finalUrl = `https://drive.google.com/uc?export=download&id=${match[1]}`;
      }
    }

    setVideo({
      url: finalUrl,
      name: finalUrl.split('/').pop()?.split('?')[0] || 'Remote Stream',
      type: 'video/mp4' // Fallback assumption
    });

    videoRef.current.src = finalUrl;
    videoRef.current.play().then(() => {
      setIsPlaying(true);
    }).catch(err => {
      console.error("Remote Playback failed:", err);
      alert("Unable to load remote video. Ensure the link is a direct video stream and CORS is enabled on the source.");
    });
    setIsUrlModalOpen(false);
  };

  const resetControlsTimer = useCallback(() => {
    setShowControls(true);
    if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    controlsTimerRef.current = window.setTimeout(() => {
      if (!isUrlModalOpen && !isSettingsOpen) {
        setShowControls(false);
      }
    }, 3000);
  }, [isUrlModalOpen, isSettingsOpen]);

  useEffect(() => {
    window.addEventListener('mousemove', resetControlsTimer);
    window.addEventListener('touchstart', resetControlsTimer);
    window.addEventListener('mousedown', resetControlsTimer);
    resetControlsTimer();
    return () => {
      window.removeEventListener('mousemove', resetControlsTimer);
      window.removeEventListener('touchstart', resetControlsTimer);
      window.removeEventListener('mousedown', resetControlsTimer);
      if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    };
  }, [resetControlsTimer]);

  useEffect(() => {
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    setShowMotionButton(isMobile);
  }, []);

  const requestMotionPermission = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const permissionState = await (DeviceOrientationEvent as any).requestPermission();
        if (permissionState === 'granted') {
          setIsMotionEnabled(true);
        }
      } catch (e) { console.error(e); }
    } else {
      setIsMotionEnabled(!isMotionEnabled);
    }
  };

  const store = useMemo(() => createXRStore({ depthSensing: true, handTracking: true }), []);

  useEffect(() => {
    const v = document.createElement('video');
    v.crossOrigin = 'anonymous';
    v.loop = true;
    v.playsInline = true;
    const updateProgress = () => { if (v.duration) setProgress((v.currentTime / v.duration) * 100); };
    v.addEventListener('timeupdate', updateProgress);
    videoRef.current = v;
    return () => {
      v.pause();
      v.removeEventListener('timeupdate', updateProgress);
      v.src = '';
    };
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      setVideo({ url, name: file.name, type: file.type });
      videoRef.current.src = url;
      videoRef.current.play().then(() => setIsPlaying(true));
    }
  };

  const togglePlay = useCallback(() => {
    if (!videoRef.current || !video) return;
    if (isPlaying) videoRef.current.pause(); else videoRef.current.play();
    setIsPlaying(!isPlaying);
  }, [isPlaying, video]);

  return (
    <div className="w-full h-screen relative bg-black select-none overflow-hidden">
      <div className="fixed top-6 right-6 z-[100]">
        <button onClick={() => store.enterVR()} className="bg-blue-600 px-6 py-3 rounded-full text-white font-bold shadow-xl hover:bg-blue-500 transition-all active:scale-95 flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 10a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-4Z"/><path d="M10 16v-2a2 2 0 0 1 4 0v2"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/></svg>
          Enter VR
        </button>
      </div>

      <div className="absolute inset-0 z-0">
        <Canvas>
          <XR store={store}>
            <Scene videoElement={videoRef.current} isPlaying={isPlaying} isMotionEnabled={isMotionEnabled} domeTilt={domeTilt} />
          </XR>
        </Canvas>
      </div>

      <Settings 
        isOpen={isSettingsOpen} 
        onToggle={() => setIsSettingsOpen(!isSettingsOpen)} 
        isMotionEnabled={isMotionEnabled} 
        onRequestMotion={requestMotionPermission} 
        domeTilt={domeTilt} 
        onTiltChange={setDomeTilt} 
        showMotionButton={showMotionButton}
        currentVideoUrl={video?.url || ''}
      />

      {isUrlModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-sm p-6">
          <div className="bg-slate-900 border border-white/10 rounded-3xl p-8 max-w-lg w-full shadow-2xl">
            <h3 className="text-xl font-black text-white mb-2">Remote Source</h3>
            <p className="text-slate-400 text-sm mb-6">Enter a direct MP4 URL or Google Drive share link.</p>
            <input 
              type="text" 
              value={remoteUrl} 
              onChange={(e) => setRemoteUrl(e.target.value)}
              placeholder="https://example.com/video.mp4" 
              className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-white mb-6 focus:ring-2 focus:ring-blue-500 outline-none"
            />
            <div className="flex gap-3">
