import React, { useRef, useEffect, useLayoutEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

// Fix for TypeScript errors: Property '...' does not exist on type 'JSX.IntrinsicElements'
declare global {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      meshBasicMaterial: any;
      shaderMaterial: any;
      color: any;
      gridHelper: any;
    }
  }
}

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
  isMotionEnabled: boolean;
  domeTilt: number;
  projectionMode: 'dome' | 'flat';
}

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null, tilt: number }> = ({ videoElement, tilt }) => {
  const meshRef = useRef<THREE.Mesh>(null!);
  const textureRef = useRef<THREE.VideoTexture | null>(null);

  useLayoutEffect(() => {
    if (meshRef.current) {
      const geometry = meshRef.current.geometry;
      const uvAttribute = geometry.attributes.uv;
      const posAttribute = geometry.attributes.position;

      const vec = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vec.fromBufferAttribute(posAttribute, i);
        vec.normalize();

        const theta = Math.acos(vec.y);
        const phi = Math.atan2(vec.z, -vec.x);
        const r = theta / Math.PI; 

        const u = 0.5 + r * Math.cos(phi);
        const v = 0.5 + r * Math.sin(phi);

        uvAttribute.setXY(i, u, v);
      }
      uvAttribute.needsUpdate = true;
    }
  }, []);

  useEffect(() => {
    if (videoElement) {
      const texture = new THREE.VideoTexture(videoElement);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textureRef.current = texture;

      if (meshRef.current) {
        const material = meshRef.current.material as THREE.MeshBasicMaterial;
        material.map = texture;
        material.needsUpdate = true;
      }
    }
  }, [videoElement]);

  return (
    <group rotation={[THREE.MathUtils.degToRad(tilt), 0, 0]}>
      <Sphere 
        ref={meshRef} 
        args={[100, 128, 128, 0, Math.PI * 2, 0, Math.PI / 2]} 
        rotation={[0, 0, 0]}
        position={[0, 0, 0]}
      >
        <meshBasicMaterial 
          side={THREE.BackSide} 
          color="#ffffff" 
        />
      </Sphere>
    </group>
  );
};

const FlatProjection: React.FC<{ videoElement: HTMLVideoElement | null }> = ({ videoElement }) => {
  const meshRef = useRef<THREE.Mesh>(null!);

  useEffect(() => {
    if (videoElement && meshRef.current) {
      const texture = new THREE.VideoTexture(videoElement);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;

      const material = meshRef.current.material as THREE.MeshBasicMaterial;
      material.map = texture;
      material.needsUpdate = true;
    }
  }, [videoElement]);

  // Plane positioned at origin, camera will move back to see it
  return (
    <mesh ref={meshRef} position={[0, 0, 0]}>
      <planeGeometry args={[100, 100]} />
      <meshBasicMaterial side={THREE.DoubleSide} color="#ffffff" />
    </mesh>
  );
};

const CameraController: React.FC<{ mode: 'dome' | 'flat', isMotionEnabled: boolean }> = ({ mode, isMotionEnabled }) => {
  const { camera } = useThree();

  useEffect(() => {
    if (mode === 'flat') {
      // Move camera outside to view the flat plane
      camera.position.set(0, 0, 160);
      camera.lookAt(0, 0, 0);
    } else {
      // Reset camera inside the dome
      camera.position.set(0, 0, 0.1);
      camera.lookAt(0, 0, -1);
    }
  }, [mode, camera]);

  return null;
};

const OrientationHandler: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  const { camera } = useThree();
  const targetQuaternion = useRef(new THREE.Quaternion());
  const currentQuaternion = useRef(new THREE.Quaternion());

  useEffect(() => {
    if (!enabled) return;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.alpha === null || e.beta === null || e.gamma === null) return;

      const alpha = THREE.MathUtils.degToRad(e.alpha); 
      const beta = THREE.MathUtils.degToRad(e.beta);   
      const gamma = THREE.MathUtils.degToRad(e.gamma); 

      const euler = new THREE.Euler();
      const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); 

      euler.set(beta, alpha, -gamma, 'YXZ'); 
      targetQuaternion.current.setFromEuler(euler);
      targetQuaternion.current.multiply(q1); 
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [enabled]);

  useFrame(() => {
    if (enabled) {
      currentQuaternion.current.slerp(targetQuaternion.current, 0.1);
      camera.quaternion.copy(currentQuaternion.current);
    }
  });

  return null;
};

const DeepSpaceBackground = () => {
  return (
    <Sphere args={[200, 32, 32]}>
      <shaderMaterial
        side={THREE.BackSide}
        transparent
        uniforms={{
          topColor: { value: new THREE.Color('#111111') },
          bottomColor: { value: new THREE.Color('#000000') },
          offset: { value: 33 },
          exponent: { value: 0.6 }
        }}
        vertexShader={`
          varying vec3 vWorldPosition;
          void main() {
            vec4 worldPosition = modelMatrix * vec4( position, 1.0 );
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
          }
        `}
        fragmentShader={`
          uniform vec3 topColor;
          uniform vec3 bottomColor;
          uniform float offset;
          uniform float exponent;
          varying vec3 vWorldPosition;
          void main() {
            float h = normalize( vWorldPosition + offset ).y;
            gl_FragColor = vec4( mix( bottomColor, topColor, max( pow( max( h , 0.0), exponent ), 0.0 ) ), 1.0 );
          }
        `}
      />
    </Sphere>
  );
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying, isMotionEnabled, domeTilt, projectionMode }) => {
  return (
    <>
      <color attach="background" args={['#000000']} />

      <PerspectiveCamera makeDefault fov={75} />

      <CameraController mode={projectionMode} isMotionEnabled={isMotionEnabled} />

      <OrbitControls 
        makeDefault 
        enabled={!isMotionEnabled}
        enablePan={false} 
        minDistance={0.01} 
        maxDistance={250} 
        enableDamping={true}
        dampingFactor={0.05}
        rotateSpeed={-0.5} 
      />

      <OrientationHandler enabled={isMotionEnabled} />

      {/* Only show background in Dome mode to avoid visual clutter in Flat mode, or keep it for consistency. Keeping it for now. */}
      <DeepSpaceBackground />

      {projectionMode === 'dome' ? (
        <DomeProjection videoElement={videoElement} tilt={domeTilt} />
      ) : (
        <FlatProjection videoElement={videoElement} />
      )}

      {/* Grid only useful for reference, maybe hide in flat mode? Keeping for now. */}
      <gridHelper args={[200, 50, 0x111111, 0x050505]} position={[0, -0.1, 0]} />
    </>
  );
};

export default Scene;

