import React, { useRef, useEffect, useLayoutEffect, useMemo } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

// Fix for TypeScript errors: Property '...' does not exist on type 'JSX.IntrinsicElements'
// Augmenting 'react' module to support JSX elements in React 18+ types
declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      mesh: any;
      meshBasicMaterial: any;
      shaderMaterial: any;
      color: any;
      gridHelper: any;
      planeGeometry: any;
      videoTexture: any;
    }
  }
}

// Also keeping global augmentation for compatibility
declare global {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      mesh: any;
      meshBasicMaterial: any;
      shaderMaterial: any;
      color: any;
      gridHelper: any;
      planeGeometry: any;
      videoTexture: any;
    }
  }
}

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
  hasVideo: boolean;
  isMotionEnabled: boolean;
  domeTilt: number;
  projectionMode: 'dome' | 'flat';
  resetTrigger: number;
}

// Shader for the pleasing dark gradient when no video is playing
const DomeGradientShader = {
  uniforms: {
    colorTop: { value: new THREE.Color('#1e293b') }, // Slate 800 (Zenith)
    colorBottom: { value: new THREE.Color('#020617') }  // Slate 950 (Horizon)
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 colorTop;
    uniform vec3 colorBottom;
    varying vec2 vUv;
    void main() {
      // Dome UVs map center (0.5, 0.5) to zenith. 
      // Calculate distance from center to determine gradient mix.
      float dist = distance(vUv, vec2(0.5));
      // smoothstep for a softer falloff, roughly 0.0 at center to 0.5 at edge
      float mixVal = smoothstep(0.0, 0.6, dist);
      vec3 color = mix(colorTop, colorBottom, mixVal);
      gl_FragColor = vec4(color, 1.0);
    }
  `
};

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null, tilt: number, hasVideo: boolean }> = ({ videoElement, tilt, hasVideo }) => {
  const meshRef = useRef<THREE.Mesh>(null!);

  useLayoutEffect(() => {
    if (meshRef.current) {
      const geometry = meshRef.current.geometry;
      const uvAttribute = geometry.attributes.uv;
      const posAttribute = geometry.attributes.position;

      const vec = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vec.fromBufferAttribute(posAttribute, i);
        vec.normalize();

        const theta = Math.acos(vec.y);
        const phi = Math.atan2(vec.z, -vec.x);
        const r = theta / Math.PI; 

        const u = 0.5 + r * Math.cos(phi);
        const v = 0.5 + r * Math.sin(phi);

        uvAttribute.setXY(i, u, v);
      }
      uvAttribute.needsUpdate = true;
    }
  }, []);

  return (
    <group rotation={[THREE.MathUtils.degToRad(tilt), 0, 0]}>
      <Sphere 
        ref={meshRef} 
        args={[100, 128, 128, 0, Math.PI * 2, 0, Math.PI / 2]} 
        rotation={[0, 0, 0]}
        position={[0, 0, 0]}
      >
        {hasVideo && videoElement ? (
          <meshBasicMaterial side={THREE.BackSide}>
             <videoTexture attach="map" args={[videoElement]} colorSpace={THREE.SRGBColorSpace} minFilter={THREE.LinearFilter} magFilter={THREE.LinearFilter} />
          </meshBasicMaterial>
        ) : (
          <shaderMaterial 
            side={THREE.BackSide}
            args={[DomeGradientShader]}
            transparent={false}
          />
        )}
      </Sphere>
    </group>
  );
};

const FlatProjection: React.FC<{ videoElement: HTMLVideoElement | null, hasVideo: boolean }> = ({ videoElement, hasVideo }) => {
  return (
    // Position at Zenith (Y=100)
    // Rotate 90deg X to face down. Rotate 180deg Z to align North (Top) with Dome North (-Z)
    <mesh rotation={[Math.PI / 2, 0, Math.PI]} position={[0, 100, 0]}>
      <planeGeometry args={[200, 200]} />
      {hasVideo && videoElement ? (
        <meshBasicMaterial side={THREE.DoubleSide}>
           <videoTexture attach="map" args={[videoElement]} colorSpace={THREE.SRGBColorSpace} minFilter={THREE.LinearFilter} magFilter={THREE.LinearFilter} />
        </meshBasicMaterial>
      ) : (
        <meshBasicMaterial side={THREE.DoubleSide} color="#1e293b" />
      )}
    </mesh>
  );
};

const CameraController: React.FC<{ mode: 'dome' | 'flat', isMotionEnabled: boolean }> = ({ mode, isMotionEnabled }) => {
  const { camera } = useThree();

  useEffect(() => {
    // Only reset position if it's the initial load or a specific reset action is desired.
    // However, to ensure seamless transition, we avoid moving the camera when switching modes.
    // The previous logic moved camera on mode switch. We now remove that to keep "view in same place".
    // We only reset FOV.

    if (camera instanceof THREE.PerspectiveCamera) {
      camera.fov = 75;
      camera.updateProjectionMatrix();
    }
  }, [mode, camera]);

  // Initial setup only
  useEffect(() => {
    // Default position: inside dome, looking slightly up/forward
    camera.position.set(0, -0.07, 0.07);
    camera.up.set(0, 1, 0); 
    camera.lookAt(0, 0, 0);
  }, []);

  return null;
};

const OrientationHandler: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  const { camera } = useThree();
  const targetQuaternion = useRef(new THREE.Quaternion());
  const currentQuaternion = useRef(new THREE.Quaternion());

  useEffect(() => {
    if (!enabled) return;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.alpha === null || e.beta === null || e.gamma === null) return;

      const alpha = THREE.MathUtils.degToRad(e.alpha); 
      const beta = THREE.MathUtils.degToRad(e.beta);   
      const gamma = THREE.MathUtils.degToRad(e.gamma); 

      const euler = new THREE.Euler();
      const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); 

      euler.set(beta, alpha, -gamma, 'YXZ'); 
      targetQuaternion.current.setFromEuler(euler);
      targetQuaternion.current.multiply(q1); 
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [enabled]);

  useFrame(() => {
    if (enabled) {
      currentQuaternion.current.slerp(targetQuaternion.current, 0.1);
      camera.quaternion.copy(currentQuaternion.current);
    }
  });

  return null;
};

const DeepSpaceBackground = () => {
  return (
    <Sphere args={[200, 32, 32]}>
      <shaderMaterial
        side={THREE.BackSide}
        transparent
        uniforms={{
          topColor: { value: new THREE.Color('#111111') },
          bottomColor: { value: new THREE.Color('#000000') },
          offset: { value: 33 },
          exponent: { value: 0.6 }
        }}
        vertexShader={`
          varying vec3 vWorldPosition;
          void main() {
            vec4 worldPosition = modelMatrix * vec4( position, 1.0 );
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
          }
        `}
        fragmentShader={`
          uniform vec3 topColor;
          uniform vec3 bottomColor;
          uniform float offset;
          uniform float exponent;
          varying vec3 vWorldPosition;
          void main() {
            float h = normalize( vWorldPosition + offset ).y;
            gl_FragColor = vec4( mix( bottomColor, topColor, max( pow( max( h , 0.0), exponent ), 0.0 ) ), 1.0 );
          }
        `}
      />
    </Sphere>
  );
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying, hasVideo, isMotionEnabled, domeTilt, projectionMode, resetTrigger }) => {
  const controlsRef = useRef<any>(null);
  const { camera, gl } = useThree();

  // Reset Logic
  useEffect(() => {
    if (resetTrigger > 0) {
      // 1. Reset FOV
      if (camera instanceof THREE.PerspectiveCamera) {
        camera.fov = 75;
        camera.updateProjectionMatrix();
      }

      // 2. Reset Transform (Unified for both modes)
      camera.position.set(0, -0.07, 0.07);
      camera.up.set(0, 1, 0);
      camera.lookAt(0, 0, 0);

      // 3. Reset Orbit Controls internal rotation state
      if (controlsRef.current) {
        controlsRef.current.reset();
      }
    }
  }, [resetTrigger, camera]);

  // Custom Zoom (FOV) Logic - Max FOV increased to 120
  useEffect(() => {
    const domElement = gl.domElement;

    // Wheel Zoom
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (camera instanceof THREE.PerspectiveCamera) {
        const sensitivity = 0.05;
        const delta = e.deltaY * sensitivity;
        const newFov = THREE.MathUtils.clamp(camera.fov + delta, 30, 120);
        camera.fov = newFov;
        camera.updateProjectionMatrix();
      }
    };

    // Pinch Zoom Variables
    let startDist = 0;
    let startFov = 75;

    const handleTouchStart = (e: TouchEvent) => {
      if (e.touches.length === 2) {
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        startDist = Math.sqrt(dx * dx + dy * dy);
        if (camera instanceof THREE.PerspectiveCamera) {
          startFov = camera.fov;
        }
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 2 && camera instanceof THREE.PerspectiveCamera) {
        e.preventDefault(); // Prevent default browser zoom

        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (startDist > 0) {
          const zoomFactor = startDist / dist; 
          const newFov = THREE.MathUtils.clamp(startFov * zoomFactor, 30, 120);

          camera.fov = newFov;
          camera.updateProjectionMatrix();
        }
      }
    };

    domElement.addEventListener('wheel', handleWheel, { passive: false });
    domElement.addEventListener('touchstart', handleTouchStart, { passive: false });
    domElement.addEventListener('touchmove', handleTouchMove, { passive: false });

    return () => {
      domElement.removeEventListener('wheel', handleWheel);
      domElement.removeEventListener('touchstart', handleTouchStart);
      domElement.removeEventListener('touchmove', handleTouchMove);
    };
  }, [gl, camera]);

  return (
    <>
      <color attach="background" args={['#000000']} />

      <PerspectiveCamera makeDefault fov={75} />

      <CameraController mode={projectionMode} isMotionEnabled={isMotionEnabled} />

      <OrbitControls 
        ref={controlsRef}
        makeDefault 
        enabled={!isMotionEnabled}
        enablePan={false} 
        enableZoom={false} // Disable default dolly zoom
        minDistance={0.01} 
        maxDistance={250} 
        enableDamping={true}
        dampingFactor={0.05}
        rotateSpeed={-0.5} 
      />

      <OrientationHandler enabled={isMotionEnabled} />

      <DeepSpaceBackground />

      {projectionMode === 'dome' ? (
        <DomeProjection videoElement={videoElement} tilt={domeTilt} hasVideo={hasVideo} />
      ) : (
        <FlatProjection videoElement={videoElement} hasVideo={hasVideo} />
      )}
    </>
  );
};

export default Scene;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { XR, createXRStore } from '@react-three/xr';
import Scene from './components/Scene';
import Controls from './components/Controls';
import AIAssistant from './components/AIAssistant';
import Settings from './components/Settings';
import { VideoData } from './types';

const App: React.FC = () => {
  const [video, setVideo] = useState<VideoData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isMotionEnabled, setIsMotionEnabled] = useState(false);
  const [showMotionButton, setShowMotionButton] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [domeTilt, setDomeTilt] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const [isUrlModalOpen, setIsUrlModalOpen] = useState(false);
  const [remoteUrl, setRemoteUrl] = useState('');

  // New State for Fullscreen and Projection Mode
  const [isImmersive, setIsImmersive] = useState(false);
  const [projectionMode, setProjectionMode] = useState<'dome' | 'flat'>('dome');

  // Camera Reset Trigger
  const [resetCameraTrigger, setResetCameraTrigger] = useState(0);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const controlsTimerRef = useRef<number | null>(null);

  // Handle Fullscreen changes (e.g. user presses ESC)
  useEffect(() => {
    const handleFullscreenChange = () => {
      const isFs = !!document.fullscreenElement;
      setIsImmersive(isFs);
      // Ensure controls are visible when exiting fullscreen
      if (!isFs) setShowControls(true);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleImmersiveMode = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.error("Error attempting to enable fullscreen:", err);
      });
    } else {
      document.exitFullscreen();
    }
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const urlParam = params.get('url');
    const tiltParam = params.get('tilt');

    if (urlParam) {
      loadVideoFromUrl(decodeURIComponent(urlParam));
    }
    if (tiltParam) {
      setDomeTilt(parseInt(tiltParam) || 0);
    }
  }, []);

  const loadVideoFromUrl = (url: string) => {
    if (!videoRef.current || !url) return;

    let finalUrl = url.trim();

    // Improved Google Drive Detection
    // Matches: /file/d/ID, open?id=ID, id=ID (in query params)
    const driveRegex = /(?:drive\.google\.com\/.*[?&]id=|drive\.google\.com\/file\/d\/|drive\.google\.com\/open\?id=)([-\w]+)/;
    const match = finalUrl.match(driveRegex);

    if (match && match[1]) {
      finalUrl = `https://drive.google.com/uc?export=download&id=${match[1]}`;
    }

    setVideo({
      url: finalUrl,
      name: finalUrl.split('/').pop()?.split('?')[0] || 'Remote Stream',
      type: 'video/mp4'
    });

    videoRef.current.src = finalUrl;
    videoRef.current.play().then(() => {
      setIsPlaying(true);
    }).catch(err => {
      console.error("Remote Playback failed:", err);
      alert("Unable to stream video. Please ensure the URL is a direct link to a video file (MP4/WebM) and that the source allows CORS requests. Standard YouTube page URLs are not supported directly.");
    });
    setIsUrlModalOpen(false);
  };

  const resetControlsTimer = useCallback(() => {
    if (isImmersive) return; // Do not show controls in immersive mode on interaction

    setShowControls(true);
    if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    controlsTimerRef.current = window.setTimeout(() => {
      if (!isUrlModalOpen && !isSettingsOpen) {
        setShowControls(false);
      }
    }, 3000);
  }, [isUrlModalOpen, isSettingsOpen, isImmersive]);

  useEffect(() => {
    const events = ['mousemove', 'touchstart', 'mousedown', 'keydown'];
    events.forEach(e => window.addEventListener(e, resetControlsTimer));
    resetControlsTimer();
    return () => {
      events.forEach(e => window.removeEventListener(e, resetControlsTimer));
      if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    };
  }, [resetControlsTimer]);

  useEffect(() => {
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    setShowMotionButton(isMobile);
  }, []);

  const requestMotionPermission = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const state = await (DeviceOrientationEvent as any).requestPermission();
        if (state === 'granted') setIsMotionEnabled(true);
      } catch (e) { console.error(e); }
    } else {
      setIsMotionEnabled(!isMotionEnabled);
    }
  };

  const store = useMemo(() => createXRStore({ depthSensing: true, handTracking: true }), []);

  useEffect(() => {
    const v = document.createElement('video');
    v.crossOrigin = 'anonymous';
    v.loop = true;
    v.playsInline = true;
    const updateProgress = () => { if (v.duration) setProgress((v.currentTime / v.duration) * 100); };
    v.addEventListener('timeupdate', updateProgress);
    videoRef.current = v;
    return () => {
      v.pause();
      v.removeEventListener('timeupdate', updateProgress);
      v.src = '';
    };
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      setVideo({ url, name: file.name, type: file.type });
      videoRef.current.src = url;
      videoRef.current.play().then(() => setIsPlaying(true));
    }
  };

  const togglePlay = useCallback(() => {
    if (!videoRef.current || !video) return;
    if (isPlaying) videoRef.current.pause(); else videoRef.current.play();
    setIsPlaying(!isPlaying);
  }, [isPlaying, video]);

  const toggleMute = useCallback(() => {
    if (!videoRef.current) return;
    videoRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  }, [isMuted]);

  return (
    <div className="w-full h-screen relative bg-black select-none overflow-hidden">
      {/* VR Button - Hidden in Immersive Mode */}
      {!isImmersive && (
        <div className="fixed top-6 right-6 z-[100] transition-opacity duration-300">
          <button onClick={() => store.enterVR()} className="bg-blue-600 px-6 py-3 rounded-full text-white font-bold shadow-xl hover:bg-blue-500 transition-all active:scale-95 flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 10a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-4Z"/><path d="M10 16v-2a2 2 0 0 1 4 0v2"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/></svg>
            Enter VR
          </button>
        </div>
      )}

      <div className="absolute inset-0 z-0">
        <Canvas flat>
          <XR store={store}>
            <Scene 
              videoElement={videoRef.current} 
              isPlaying={isPlaying} 
              hasVideo={!!video}
              isMotionEnabled={isMotionEnabled} 
              domeTilt={domeTilt} 
              projectionMode={projectionMode}
              resetTrigger={resetCameraTrigger}
            />
          </XR>
        </Canvas>
      </div>

      {/* UI Components - Hidden in Immersive Mode */}
      {!isImmersive && (
        <>
          <Settings 
            isOpen={isSettingsOpen} 
            onToggle={() => setIsSettingsOpen(!isSettingsOpen)} 
            isMotionEnabled={isMotionEnabled} 
            onRequestMotion={requestMotionPermission} 
            domeTilt={domeTilt} 
            onTiltChange={setDomeTilt} 
            showMotionButton={showMotionButton}
            currentVideoUrl={video?.url || ''}
            projectionMode={projectionMode}
            onProjectionModeChange={setProjectionMode}
          />

          {video && <AIAssistant currentVideoName={video.name} />}

          {isUrlModalOpen && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-md p-6">
              <div className="bg-slate-900 border border-white/10 rounded-3xl p-8 max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                <h3 className="text-xl font-black text-white mb-2">Remote Source</h3>
                <p className="text-slate-400 text-sm mb-4">Launch a direct video stream (MP4/WebM).</p>

                <div className="space-y-4 mb-6">
                  <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-xl text-[10px] leading-relaxed text-blue-300">
                    <b>Google Drive:</b> Paste any Share Link. We will auto-convert it.<br/>
                    <b>YouTube:</b> Standard YouTube links are not supported.
                  </div>
                  <input 
                    type="text" 
                    value={remoteUrl} 
                    onChange={(e) => setRemoteUrl(e.target.value)}
                    placeholder="https://drive.google.com/file/d/..." 
                    className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none placeholder:text-white/20"
                  />
                </div>

                <div className="flex gap-3">
                  <button onClick={() => setIsUrlModalOpen(false)} className="flex-1 py-3 text-slate-400 font-bold hover:text-white transition-colors">Cancel</button>
                  <button onClick={() => loadVideoFromUrl(remoteUrl)} className="flex-1 bg-blue-600 py-3 rounded-xl text-white font-bold hover:bg-blue-500 shadow-lg shadow-blue-600/20">Launch Journey</button>
                </div>
              </div>
            </div>
          )}

          {!video && !isUrlModalOpen && (
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
              <div className="p-8 bg-slate-900/80 backdrop-blur-md rounded-3xl border border-white/10 text-center max-w-md shadow-2xl pointer-events-auto">
                <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-4 tracking-tighter">NOVA DOME</h1>
                <p className="text-slate-300 mb-8 text-sm leading-relaxed">Experience immersive <b>Dome Master</b> media. Upload locally or provide a remote stream.</p>
                <div className="flex flex-col gap-3">
                  <label className="bg-white text-slate-900 px-8 py-4 rounded-xl font-bold cursor-pointer hover:bg-blue-50 transition-all shadow-lg active:scale-95 text-center">
                    Select Local File
                    <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
                  </label>
                  <button onClick={() => setIsUrlModalOpen(true)} className="text-blue-400 font-bold py-2 hover:text-blue-300 transition-colors">Stream Remote URL</button>
                </div>
              </div>
            </div>
          )}

          {video && (
            <div className={`transition-opacity duration-700 ${showControls ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              <Controls 
                isPlaying={isPlaying} 
                onTogglePlay={togglePlay} 
                isMuted={isMuted}
                onToggleMute={toggleMute}
                onFileSelect={handleFileChange} 
                onUrlSelect={() => setIsUrlModalOpen(true)} 
                videoName={video.name} 
                progress={progress} 
                onToggleFullscreen={toggleImmersiveMode}
                onResetCamera={() => setResetCameraTrigger(p => p + 1)}
              />
            </div>
          )}

          <div className={`fixed top-6 left-12 pointer-events-none z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-20'}`}>
            <div className="flex flex-col gap-1">
              <span className="text-[10px] font-black text-white/30 tracking-[0.2em] uppercase">Status Check</span>
              <div className="flex items-center gap-2">
                <div className={`w-1.5 h-1.5 rounded-full ${isPlaying ? 'bg-blue-500 shadow-[0_0_8px_#3b82f6]' : 'bg-red-500'}`}></div>
                <span className="text-white/80 text-[10px] font-bold tracking-widest uppercase">{isPlaying ? 'Active Stream' : 'Systems Standby'}</span>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useLayoutEffect, useMemo } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Sphere, PerspectiveCamera, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

// Fix for TypeScript errors: Property '...' does not exist on type 'JSX.IntrinsicElements'
// Augmenting 'react' module to support JSX elements in React 18+ types
declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      mesh: any;
      meshBasicMaterial: any;
      shaderMaterial: any;
      color: any;
      gridHelper: any;
      planeGeometry: any;
      videoTexture: any;
    }
  }
}

// Also keeping global augmentation for compatibility
declare global {
  namespace JSX {
    interface IntrinsicElements {
      group: any;
      mesh: any;
      meshBasicMaterial: any;
      shaderMaterial: any;
      color: any;
      gridHelper: any;
      planeGeometry: any;
      videoTexture: any;
    }
  }
}

interface SceneProps {
  videoElement: HTMLVideoElement | null;
  isPlaying: boolean;
  hasVideo: boolean;
  isMotionEnabled: boolean;
  domeTilt: number;
  projectionMode: 'dome' | 'flat';
  resetTrigger: number;
}

// Shader for the pleasing dark gradient when no video is playing
const DomeGradientShader = {
  uniforms: {
    colorTop: { value: new THREE.Color('#1e293b') }, // Slate 800 (Zenith)
    colorBottom: { value: new THREE.Color('#020617') }  // Slate 950 (Horizon)
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 colorTop;
    uniform vec3 colorBottom;
    varying vec2 vUv;
    void main() {
      // Dome UVs map center (0.5, 0.5) to zenith. 
      // Calculate distance from center to determine gradient mix.
      float dist = distance(vUv, vec2(0.5));
      // smoothstep for a softer falloff, roughly 0.0 at center to 0.5 at edge
      float mixVal = smoothstep(0.0, 0.6, dist);
      vec3 color = mix(colorTop, colorBottom, mixVal);
      gl_FragColor = vec4(color, 1.0);
    }
  `
};

const DomeProjection: React.FC<{ videoElement: HTMLVideoElement | null, tilt: number, hasVideo: boolean }> = ({ videoElement, tilt, hasVideo }) => {
  const meshRef = useRef<THREE.Mesh>(null!);

  useLayoutEffect(() => {
    if (meshRef.current) {
      const geometry = meshRef.current.geometry;
      const uvAttribute = geometry.attributes.uv;
      const posAttribute = geometry.attributes.position;

      const vec = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vec.fromBufferAttribute(posAttribute, i);
        vec.normalize();

        const theta = Math.acos(vec.y);

        // Use (-z, x) to correctly orient:
        // 1. Front (-Z) maps to Top of texture (North)
        // 2. Left (-X) maps to Left of texture (West) - No horizontal flip
        const phi = Math.atan2(-vec.z, vec.x); 

        const r = theta / Math.PI; 

        const u = 0.5 + r * Math.cos(phi);
        const v = 0.5 + r * Math.sin(phi);

        uvAttribute.setXY(i, u, v);
      }
      uvAttribute.needsUpdate = true;
    }
  }, []);

  return (
    <group rotation={[THREE.MathUtils.degToRad(tilt), 0, 0]}>
      <Sphere 
        ref={meshRef} 
        args={[100, 128, 128, 0, Math.PI * 2, 0, Math.PI / 2]} 
        rotation={[0, 0, 0]}
        position={[0, 0, 0]}
      >
        {hasVideo && videoElement ? (
          <meshBasicMaterial side={THREE.BackSide}>
             <videoTexture attach="map" args={[videoElement]} colorSpace={THREE.SRGBColorSpace} minFilter={THREE.LinearFilter} magFilter={THREE.LinearFilter} />
          </meshBasicMaterial>
        ) : (
          <shaderMaterial 
            side={THREE.BackSide}
            args={[DomeGradientShader]}
            transparent={false}
          />
        )}
      </Sphere>
    </group>
  );
};

const FlatProjection: React.FC<{ videoElement: HTMLVideoElement | null, hasVideo: boolean }> = ({ videoElement, hasVideo }) => {
  return (
    // Position at Zenith (Y=100)
    // Rotate 90deg X to face down.
    // Alignment: -Z in World Space corresponds to -Z (Top) of Texture.
    // Matches Dome Projection where Front (-Z) is Top.
    <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, 100, 0]}>
      <planeGeometry args={[200, 200]} />
      {hasVideo && videoElement ? (
        <meshBasicMaterial side={THREE.DoubleSide}>
           <videoTexture attach="map" args={[videoElement]} colorSpace={THREE.SRGBColorSpace} minFilter={THREE.LinearFilter} magFilter={THREE.LinearFilter} />
        </meshBasicMaterial>
      ) : (
        <meshBasicMaterial side={THREE.DoubleSide} color="#1e293b" />
      )}
    </mesh>
  );
};

const CameraController: React.FC<{ mode: 'dome' | 'flat', isMotionEnabled: boolean }> = ({ mode, isMotionEnabled }) => {
  const { camera } = useThree();

  useEffect(() => {
    // Only reset position if it's the initial load or a specific reset action is desired.
    // However, to ensure seamless transition, we avoid moving the camera when switching modes.
    // The previous logic moved camera on mode switch. We now remove that to keep "view in same place".
    // We only reset FOV.

    if (camera instanceof THREE.PerspectiveCamera) {
      camera.fov = 75;
      camera.updateProjectionMatrix();
    }
  }, [mode, camera]);

  // Initial setup only
  useEffect(() => {
    // Default position: inside dome, looking slightly up/forward towards -Z (Front/North)
    // Position (0, -0.07, 0.07) + LookAt (0,0,0) creates a 45 degree upward angle towards -Z.
    camera.position.set(0, -0.07, 0.07);
    camera.up.set(0, 1, 0); 
    camera.lookAt(0, 0, 0);
  }, []);

  return null;
};

const OrientationHandler: React.FC<{ enabled: boolean }> = ({ enabled }) => {
  const { camera } = useThree();
  const targetQuaternion = useRef(new THREE.Quaternion());
  const currentQuaternion = useRef(new THREE.Quaternion());

  useEffect(() => {
    if (!enabled) return;

    const handleOrientation = (e: DeviceOrientationEvent) => {
      if (e.alpha === null || e.beta === null || e.gamma === null) return;

      const alpha = THREE.MathUtils.degToRad(e.alpha); 
      const beta = THREE.MathUtils.degToRad(e.beta);   
      const gamma = THREE.MathUtils.degToRad(e.gamma); 

      const euler = new THREE.Euler();
      const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5)); 

      euler.set(beta, alpha, -gamma, 'YXZ'); 
      targetQuaternion.current.setFromEuler(euler);
      targetQuaternion.current.multiply(q1); 
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [enabled]);

  useFrame(() => {
    if (enabled) {
      currentQuaternion.current.slerp(targetQuaternion.current, 0.1);
      camera.quaternion.copy(currentQuaternion.current);
    }
  });

  return null;
};

const DeepSpaceBackground = () => {
  return (
    <Sphere args={[200, 32, 32]}>
      <shaderMaterial
        side={THREE.BackSide}
        transparent
        uniforms={{
          topColor: { value: new THREE.Color('#111111') },
          bottomColor: { value: new THREE.Color('#000000') },
          offset: { value: 33 },
          exponent: { value: 0.6 }
        }}
        vertexShader={`
          varying vec3 vWorldPosition;
          void main() {
            vec4 worldPosition = modelMatrix * vec4( position, 1.0 );
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
          }
        `}
        fragmentShader={`
          uniform vec3 topColor;
          uniform vec3 bottomColor;
          uniform float offset;
          uniform float exponent;
          varying vec3 vWorldPosition;
          void main() {
            float h = normalize( vWorldPosition + offset ).y;
            gl_FragColor = vec4( mix( bottomColor, topColor, max( pow( max( h , 0.0), exponent ), 0.0 ) ), 1.0 );
          }
        `}
      />
    </Sphere>
  );
};

const Scene: React.FC<SceneProps> = ({ videoElement, isPlaying, hasVideo, isMotionEnabled, domeTilt, projectionMode, resetTrigger }) => {
  const controlsRef = useRef<any>(null);
  const { camera, gl } = useThree();

  // Reset Logic
  useEffect(() => {
    if (resetTrigger > 0) {
      // 1. Reset FOV
      if (camera instanceof THREE.PerspectiveCamera) {
        camera.fov = 75;
        camera.updateProjectionMatrix();
      }

      // 2. Reset Transform (Unified for both modes)
      camera.position.set(0, -0.07, 0.07);
      camera.up.set(0, 1, 0);
      camera.lookAt(0, 0, 0);

      // 3. Reset Orbit Controls internal rotation state
      if (controlsRef.current) {
        controlsRef.current.reset();
      }
    }
  }, [resetTrigger, camera]);

  // Custom Zoom (FOV) Logic - Max FOV increased to 120
  useEffect(() => {
    const domElement = gl.domElement;

    // Wheel Zoom
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (camera instanceof THREE.PerspectiveCamera) {
        const sensitivity = 0.05;
        const delta = e.deltaY * sensitivity;
        const newFov = THREE.MathUtils.clamp(camera.fov + delta, 30, 120);
        camera.fov = newFov;
        camera.updateProjectionMatrix();
      }
    };

    // Pinch Zoom Variables
    let startDist = 0;
    let startFov = 75;

    const handleTouchStart = (e: TouchEvent) => {
      if (e.touches.length === 2) {
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        startDist = Math.sqrt(dx * dx + dy * dy);
        if (camera instanceof THREE.PerspectiveCamera) {
          startFov = camera.fov;
        }
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 2 && camera instanceof THREE.PerspectiveCamera) {
        e.preventDefault(); // Prevent default browser zoom

        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (startDist > 0) {
          const zoomFactor = startDist / dist; 
          const newFov = THREE.MathUtils.clamp(startFov * zoomFactor, 30, 120);

          camera.fov = newFov;
          camera.updateProjectionMatrix();
        }
      }
    };

    domElement.addEventListener('wheel', handleWheel, { passive: false });
    domElement.addEventListener('touchstart', handleTouchStart, { passive: false });
    domElement.addEventListener('touchmove', handleTouchMove, { passive: false });

    return () => {
      domElement.removeEventListener('wheel', handleWheel);
      domElement.removeEventListener('touchstart', handleTouchStart);
      domElement.removeEventListener('touchmove', handleTouchMove);
    };
  }, [gl, camera]);

  return (
    <>
      <color attach="background" args={['#000000']} />

      <PerspectiveCamera makeDefault fov={75} />

      <CameraController mode={projectionMode} isMotionEnabled={isMotionEnabled} />

      <OrbitControls 
        ref={controlsRef}
        makeDefault 
        enabled={!isMotionEnabled}
        enablePan={false} 
        enableZoom={false} // Disable default dolly zoom
        minDistance={0.01} 
        maxDistance={250} 
        enableDamping={true}
        dampingFactor={0.05}
        rotateSpeed={-0.5} 
      />

      <OrientationHandler enabled={isMotionEnabled} />

      <DeepSpaceBackground />

      {projectionMode === 'dome' ? (
        <DomeProjection videoElement={videoElement} tilt={domeTilt} hasVideo={hasVideo} />
      ) : (
        <FlatProjection videoElement={videoElement} hasVideo={hasVideo} />
      )}
    </>
  );
};

export default Scene;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { XR, createXRStore } from '@react-three/xr';
import Scene from './components/Scene';
import Controls from './components/Controls';
import AIAssistant from './components/AIAssistant';
import Settings from './components/Settings';
import { VideoData } from './types';

const App: React.FC = () => {
  const [video, setVideo] = useState<VideoData | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isMotionEnabled, setIsMotionEnabled] = useState(false);
  const [showMotionButton, setShowMotionButton] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [domeTilt, setDomeTilt] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const [isUrlModalOpen, setIsUrlModalOpen] = useState(false);
  const [remoteUrl, setRemoteUrl] = useState('');

  // New State for Fullscreen and Projection Mode
  const [isImmersive, setIsImmersive] = useState(false);
  const [projectionMode, setProjectionMode] = useState<'dome' | 'flat'>('dome');

  // Camera Reset Trigger
  const [resetCameraTrigger, setResetCameraTrigger] = useState(0);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const controlsTimerRef = useRef<number | null>(null);

  // Handle Fullscreen changes (e.g. user presses ESC)
  useEffect(() => {
    const handleFullscreenChange = () => {
      const isFs = !!document.fullscreenElement;
      setIsImmersive(isFs);
      // Ensure controls are visible when exiting fullscreen
      if (!isFs) setShowControls(true);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleImmersiveMode = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.error("Error attempting to enable fullscreen:", err);
      });
    } else {
      document.exitFullscreen();
    }
  };

  const loadVideoFromUrl = useCallback((url: string, autoPlay: boolean = true) => {
    if (!videoRef.current || !url) return;

    let finalUrl = url.trim();

    // Improved Google Drive Detection
    // Matches: /file/d/ID, open?id=ID, id=ID (in query params)
    const driveRegex = /(?:drive\.google\.com\/.*[?&]id=|drive\.google\.com\/file\/d\/|drive\.google\.com\/open\?id=)([-\w]+)/;
    const match = finalUrl.match(driveRegex);

    if (match && match[1]) {
      finalUrl = `https://drive.google.com/uc?export=download&id=${match[1]}`;
    }

    setVideo({
      url: finalUrl,
      name: finalUrl.split('/').pop()?.split('?')[0] || 'Remote Stream',
      type: 'video/mp4'
    });

    videoRef.current.src = finalUrl;

    if (autoPlay) {
      videoRef.current.play().then(() => {
        setIsPlaying(true);
      }).catch(err => {
        console.warn("Autoplay blocked or failed:", err);
        setIsPlaying(false);
      });
    } else {
      setIsPlaying(false);
    }

    setIsUrlModalOpen(false);
  }, []);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const urlParam = params.get('url');
    const tiltParam = params.get('tilt');
    const autoParam = params.get('autoplay');

    // Default autoplay to true unless explicitly set to '0' or 'false'
    const shouldAutoPlay = autoParam !== '0' && autoParam !== 'false';

    if (urlParam) {
      loadVideoFromUrl(decodeURIComponent(urlParam), shouldAutoPlay);
    }
    if (tiltParam) {
      setDomeTilt(parseInt(tiltParam) || 0);
    }
  }, [loadVideoFromUrl]);

  const resetControlsTimer = useCallback(() => {
    if (isImmersive) return; // Do not show controls in immersive mode on interaction

    setShowControls(true);
    if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    controlsTimerRef.current = window.setTimeout(() => {
      if (!isUrlModalOpen && !isSettingsOpen) {
        setShowControls(false);
      }
    }, 3000);
  }, [isUrlModalOpen, isSettingsOpen, isImmersive]);

  useEffect(() => {
    const events = ['mousemove', 'touchstart', 'mousedown', 'keydown'];
    events.forEach(e => window.addEventListener(e, resetControlsTimer));
    resetControlsTimer();
    return () => {
      events.forEach(e => window.removeEventListener(e, resetControlsTimer));
      if (controlsTimerRef.current) window.clearTimeout(controlsTimerRef.current);
    };
  }, [resetControlsTimer]);

  useEffect(() => {
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    setShowMotionButton(isMobile);
  }, []);

  const requestMotionPermission = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const state = await (DeviceOrientationEvent as any).requestPermission();
        if (state === 'granted') setIsMotionEnabled(true);
      } catch (e) { console.error(e); }
    } else {
      setIsMotionEnabled(!isMotionEnabled);
    }
  };

  const store = useMemo(() => createXRStore({ depthSensing: true, handTracking: true }), []);

  useEffect(() => {
    const v = document.createElement('video');
    v.crossOrigin = 'anonymous';
    v.loop = true;
    v.playsInline = true;
    const updateProgress = () => { if (v.duration) setProgress((v.currentTime / v.duration) * 100); };
    v.addEventListener('timeupdate', updateProgress);
    videoRef.current = v;
    return () => {
      v.pause();
      v.removeEventListener('timeupdate', updateProgress);
      v.src = '';
    };
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && videoRef.current) {
      const url = URL.createObjectURL(file);
      setVideo({ url, name: file.name, type: file.type });
      videoRef.current.src = url;
      videoRef.current.play().then(() => setIsPlaying(true));
    }
  };

  const togglePlay = useCallback(() => {
    if (!videoRef.current || !video) return;
    if (isPlaying) videoRef.current.pause(); else videoRef.current.play();
    setIsPlaying(!isPlaying);
  }, [isPlaying, video]);

  const toggleMute = useCallback(() => {
    if (!videoRef.current) return;
    videoRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  }, [isMuted]);

  return (
    <div className="w-full h-screen relative bg-black select-none overflow-hidden">
      {/* VR Button - Hidden in Immersive Mode */}
      {!isImmersive && (
        <div className="fixed top-6 right-6 z-[100] transition-opacity duration-300">
          <button onClick={() => store.enterVR()} className="bg-blue-600 px-6 py-3 rounded-full text-white font-bold shadow-xl hover:bg-blue-500 transition-all active:scale-95 flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 10a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-4Z"/><path d="M10 16v-2a2 2 0 0 1 4 0v2"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/></svg>
            Enter VR
          </button>
        </div>
      )}

      <div className="absolute inset-0 z-0">
        <Canvas flat>
          <XR store={store}>
            <Scene 
              videoElement={videoRef.current} 
              isPlaying={isPlaying} 
              hasVideo={!!video}
              isMotionEnabled={isMotionEnabled} 
              domeTilt={domeTilt} 
              projectionMode={projectionMode}
              resetTrigger={resetCameraTrigger}
            />
          </XR>
        </Canvas>
      </div>

      {/* UI Components - Hidden in Immersive Mode */}
      {!isImmersive && (
        <>
          <Settings 
            isOpen={isSettingsOpen} 
            onToggle={() => setIsSettingsOpen(!isSettingsOpen)} 
            isMotionEnabled={isMotionEnabled} 
            onRequestMotion={requestMotionPermission} 
            domeTilt={domeTilt} 
            onTiltChange={setDomeTilt} 
            showMotionButton={showMotionButton}
            currentVideoUrl={video?.url || ''}
            projectionMode={projectionMode}
            onProjectionModeChange={setProjectionMode}
          />

          {video && <AIAssistant currentVideoName={video.name} />}

          {isUrlModalOpen && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-md p-6">
              <div className="bg-slate-900 border border-white/10 rounded-3xl p-8 max-w-lg w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                <h3 className="text-xl font-black text-white mb-2">Remote Source</h3>
                <p className="text-slate-400 text-sm mb-4">Launch a direct video stream (MP4/WebM).</p>

                <div className="space-y-4 mb-6">
                  <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-xl text-[10px] leading-relaxed text-blue-300">
                    <b>Google Drive:</b> Paste any Share Link. We will auto-convert it.<br/>
                    <b>YouTube:</b> Standard YouTube links are not supported.
                  </div>
                  <input 
                    type="text" 
                    value={remoteUrl} 
                    onChange={(e) => setRemoteUrl(e.target.value)}
                    placeholder="https://drive.google.com/file/d/..." 
                    className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-3 text-white focus:ring-2 focus:ring-blue-500 outline-none placeholder:text-white/20"
                  />
                </div>

                <div className="flex gap-3">
                  <button onClick={() => setIsUrlModalOpen(false)} className="flex-1 py-3 text-slate-400 font-bold hover:text-white transition-colors">Cancel</button>
                  <button onClick={() => loadVideoFromUrl(remoteUrl)} className="flex-1 bg-blue-600 py-3 rounded-xl text-white font-bold hover:bg-blue-500 shadow-lg shadow-blue-600/20">Launch Journey</button>
                </div>
              </div>
            </div>
          )}

          {!video && !isUrlModalOpen && (
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
              <div className="p-8 bg-slate-900/80 backdrop-blur-md rounded-3xl border border-white/10 text-center max-w-md shadow-2xl pointer-events-auto">
                <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400 mb-4 tracking-tighter">NOVA DOME</h1>
                <p className="text-slate-300 mb-8 text-sm leading-relaxed">Experience immersive <b>Dome Master</b> media. Upload locally or provide a remote stream.</p>
                <div className="flex flex-col gap-3">
                  <label className="bg-white text-slate-900 px-8 py-4 rounded-xl font-bold cursor-pointer hover:bg-blue-50 transition-all shadow-lg active:scale-95 text-center">
                    Select Local File
                    <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
                  </label>
                  <button onClick={() => setIsUrlModalOpen(true)} className="text-blue-400 font-bold py-2 hover:text-blue-300 transition-colors">Stream Remote URL</button>
                </div>
              </div>
            </div>
          )}

          {video && (
            <div className={`transition-opacity duration-700 ${showControls ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              <Controls 
                isPlaying={isPlaying} 
                onTogglePlay={togglePlay} 
                isMuted={isMuted}
                onToggleMute={toggleMute}
                onFileSelect={handleFileChange} 
                onUrlSelect={() => setIsUrlModalOpen(true)} 
                videoName={video.name} 
                progress={progress} 
                onToggleFullscreen={toggleImmersiveMode}
                onResetCamera={() => setResetCameraTrigger(p => p + 1)}
              />
            </div>
          )}

          <div className={`fixed top-6 left-12 pointer-events-none z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-20'}`}>
            <div className="flex flex-col gap-1">
              <span className="text-[10px] font-black text-white/30 tracking-[0.2em] uppercase">Status Check</span>
              <div className="flex items-center gap-2">
                <div className={`w-1.5 h-1.5 rounded-full ${isPlaying ? 'bg-blue-500 shadow-[0_0_8px_#3b82f6]' : 'bg-red-500'}`}></div>
                <span className="text-white/80 text-[10px] font-bold tracking-widest uppercase">{isPlaying ? 'Active Stream' : 'Systems Standby'}</span>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

