    // Default autoplay to true unless explicitly set to '0' or 'false'
    const shouldAutoPlay = autoParam !== '0' && autoParam !== 'false';

    if (urlParam) {
      loadVideoFromUrl(decodeURIComponent(urlParam), shouldAutoPlay);
    }
    if (tiltParam) {
      setDomeTilt(parseInt(tiltParam) || 0);
